parameters.jsCode:
// CorpFlowAI heartbeat evaluation (read-only). Exception-only paging per issue #658.
// Routine open-PR age / CI-surfacing alerts removed — GitHub is source of truth.
// Canonical mirror: lib/server/ops-notification-policy.js evaluateGithubHeartbeatSignals() + filterHeartbeatAlertsByHourDedupe()
const now = Date.now();
const H = 3600 * 1000;
const DIGEST_STALE_H = 12;
const WIP_CAP = 2;
const hourBucket = Math.floor(now / H);
const staticData = $getWorkflowStaticData('global');
if (!staticData.heartbeatSeen || typeof staticData.heartbeatSeen !== 'object') staticData.heartbeatSeen = {};
const seen = staticData.heartbeatSeen;
const comments = $('GitHub: #493 comments').all().map(i => i.json).flat();
const prs = $('GitHub: open PRs').all().map(i => i.json).flat();
const alerts = [];
const digest = comments.find(c => c && typeof c.body === 'string' && c.body.includes('Dispatcher Digest'));
const lastDigestMs = digest ? new Date(digest.created_at).getTime() : 0;
if (!digest || (now - lastDigestMs) > DIGEST_STALE_H * H) {
  const staleH = digest ? Math.round((now - lastDigestMs) / H) : null;
  alerts.push({ kind: 'digest_stale', target: '#493', severity: 'error', stale: staleH ? staleH + 'h' : 'none found', why: 'no dispatcher digest within the 12h active-day window', next: 'Cursor posts a dispatcher digest', anton: false });
}
if (Array.isArray(prs) && prs.length > WIP_CAP) {
  alerts.push({ kind: 'wip_cap', target: 'open PRs', severity: 'error', stale: 'n/a', why: prs.length + ' open PRs exceeds WIP cap of ' + WIP_CAP, next: 'merge or close PRs to drain WIP', anton: true });
}
const candidates = alerts.filter(a => a.severity === 'error' || a.severity === 'fatal');
const paging = [];
for (const a of candidates) {
  const key = a.kind + '|' + a.target + '|' + hourBucket;
  if (seen[key]) continue;
  seen[key] = true;
  paging.push(a);
}
for (const key of Object.keys(seen)) {
  const parts = key.split('|');
  const bucket = Number(parts[parts.length - 1]);
  if (Number.isFinite(bucket) && bucket < hourBucket) delete seen[key];
}
return [{ json: { checked: ['#493 comments', 'open PRs', 'open Action-Plan issues'], alert_count: paging.length, alerts: paging, all_signals: alerts, evaluated_at_utc: new Date(now).toISOString(), dedupe_hour_bucket: hourBucket } }];

